-- open / close every instance of the layers (soccer_top_menu has no SwitchLayerOpenOrClose of its own)
function BBT_SwitchLayers(t, open)
  for _, l in ipairs(t or {}) do
    local n = funcLuaMenuCommand(1175615627, l) or 0
    for i = 0, n - 1 do
      if open then
        funcLuaMenuCommand(629267548, l, i)
      else
        funcLuaMenuCommand(1273612389, l, i)
      end
    end
  end
end

function BBT_ShowLayers(t, on)
  for _, l in ipairs(t or {}) do
    local n = funcLuaMenuCommand(1175615627, l) or 0
    for i = 0, n - 1 do
      funcLuaMenuCommand(711242136, l, i, on)
    end
  end
end

