-- 1.61.0 (owner 2026-10-29): «Plantilla» opens the game's own team dock for the team the player uses in this league
-- (VRFW_TeamEditor: a temporary copy of the team in the dock inside a save session that is undone when it closes, so
-- the player's own teams and save never change). The order and formation left there go to the run
-- (CMND_BBD_LEAGUE_SQUAD_SET, scripts\league_squad.lua) and are played from the next league match on. The Active team
-- tile opens the player's own dock as it is (that team is the one it plays). false = no dock (the Draft team, the
-- framework's editor missing or refused): the caller shows the read-only squad page.
function BBT_HubTeamEditor()
  local H = BattleBayDeluxe.Tournament.HUB
  if type(VRFW_TeamEditor) ~= "table" then
    BBT_Log("hub: no VRFW_TeamEditor (VRFW < 2.226.0): the squad page")
    return false
  end
  local sq = BBT_Call(H.SQUAD_GET)
  if type(sq) ~= "table" or not sq.ok then
    BBT_Log("hub: league squad not read:", type(sq) == "table" and tostring(sq.why) or "no answer")
    return false
  end
  if sq.kind == "draft" then
    BBT_Log("hub: the Draft team keeps its drafted order: the squad page")
    return false
  end
  if sq.kind ~= "own" then
    local can, why = VRFW_TeamEditor.CanOpen()
    if not can then
      BBT_Log("hub: team editor refused:", why)
      return false
    end
  end
  local okn, _, name = pcall(funcLuaCommand, H.TEAM_INFO, sq.team, 2)
  BBT_Close()
  -- 1.63.0 (owner in game 2026-10-29: «Campaña», «SIGUIENTE», «Ayuda», the BB logo drawn over the dock): the top menu's
  -- own layers stay closed / hidden while the dock is up, exactly as under the overlay (BBT_Open); the button guide
  -- layer stays (the dock writes its guide there). BBT_Open puts them right again afterwards.
  BBT_SwitchLayers(BattleBayDeluxe.TournamentHost.close, false)
  BBT_ShowLayers(BattleBayDeluxe.TournamentHost.hide, false)
  BBT_BgLogo(false)
  for _, l in ipairs(BattleBayDeluxe.TournamentHost.lists or {}) do
    funcLuaMenuCommand(3518307824, l, false)
  end
  -- 1.68.0 (owner 2026-10-29: «Revisa el fondo también», the plain Battle Bay backdrop under the dock): the hub's own
  -- background (vroad04_01_p1_bg, as BBT_Open places it; BBT_Close closed it) is open under the dock and stays open
  -- for the hub that comes back after it
  local G = BattleBayDeluxe.Tournament.G
  local sy = (G.BG_BOTTOM - G.BG_TOP) / G.BG_H
  bbt_open_layer(BattleBayDeluxe.Tournament.L.bg, 0)
  funcLuaMenuCommand(BattleBayDeluxe.Tournament.C.SCALE, BattleBayDeluxe.Tournament.L.bg, 1, sy, 1, 0)
  funcLuaMenuCommand(BattleBayDeluxe.Tournament.C.POS, BattleBayDeluxe.Tournament.L.bg, 0, -(G.BG_TOP - G.BG_Y * sy), 0, 0)
  funcLuaMenuCommand(BattleBayDeluxe.Tournament.C.VISIBLE, BattleBayDeluxe.Tournament.L.bg, 0, true)
  -- 1.67.0 (owner 2026-10-29): a league team is not one of the player's: the editor's foreign team mode (its own
  -- coach, kit, emblem, tactics, synergies and stadium; no bank, no team switching, no active team)
  local own = sq.kind == "own"
  local res, why = VRFW_TeamEditor.Run({
    owner = "BattleBayDeluxe", host = BattleBayDeluxe.TournamentHost.menu, own = own, foreign = not own, members = sq.members,
    formation = sq.formation, level = sq.level, emblem = sq.emblem, name = okn and type(name) == "string" and name or nil,
    coach = sq.coach, kit = sq.kit, tactics = sq.tactics, synergies = sq.synergies, stadium = sq.stadium,
    -- 1.69.0 (owner 2026-10-29): the list offers the lineup, «Vínculo de Afinidad» and «Comandos de hipertécnicas»
    rows = (VRFW_TeamEditor.ROW ~= nil) and { VRFW_TeamEditor.ROW.LINEUP, VRFW_TeamEditor.ROW.BONDS,
      VRFW_TeamEditor.ROW.HYPER_COMMANDS } or nil,
  })
  -- 1.67.0 (owner 2026-10-29: «Al regresar se queda así», an empty screen under the dock's guide): the card ids are
  -- unsigned 32-bit, past the range of this Lua's "%d" (loader.log: «bad argument #3 to 'format' (not a number in
  -- proper range)»), so the hub was never opened again after the dock closed. The ids go out as "%.0f", and whatever
  -- the order's write does, the hub opens again as soon as the editor returns.
  local okw, saved = pcall(function()
    if res and not res.own then
      local parts = {}
      for _, m in ipairs(res.members or {}) do
        parts[#parts + 1] = string.format("%.0f:%.0f", m[1], m[2])
      end
      local r = BBT_Call(H.SQUAD_SET, res.formation or 0, table.concat(parts, ","))
      local kept = type(r) == "table" and r.ok == true
      BBT_Log("hub: league lineup from the dock:", #parts, "players,", res.foreign or 0, "club players, kept",
        tostring(kept), type(r) == "table" and tostring(r.why or "") or "no answer")
      return kept
    elseif not res then
      -- nothing to keep (the dock did not open, the session was refused): the log says why, no message
      BBT_Log("hub: team editor:", tostring(why))
    end
    return true
  end)
  if not okw then
    BBT_Log("hub: league lineup not kept:", tostring(saved))
    saved = false
  end
  for _, l in ipairs(BattleBayDeluxe.TournamentHost.lists or {}) do
    funcLuaMenuCommand(3518307824, l, true)
  end
  BBT_Open(H.PAGE)
  if not saved and BattleBayDeluxe.TournamentState.open then
    BBT_Window(BBT_Id("squad_not_saved"), 1)
  end
  return true
end

-- the side menu's cursor and the dashboard's focus to the drawing menu
function BBT_HubNavParam()
  VRFW_Param.Clear(BattleBayDeluxe.Tournament.HUB.P_NAV)
  VRFW_Param.Set(BattleBayDeluxe.Tournament.HUB.P_NAV, BattleBayDeluxe.TournamentState.hub_nav or 0)
  VRFW_Param.Clear(BattleBayDeluxe.Tournament.HUB.P_FOCUS)
  VRFW_Param.Set(BattleBayDeluxe.Tournament.HUB.P_FOCUS, BattleBayDeluxe.TournamentState.hub_focus or 0)
end

-- the dashboard's focus to panel k (0 = back to the side menu), the dashboard drawn again; silent = no move sound
function BBT_HubFocus(k, silent)
  BattleBayDeluxe.TournamentState.hub_focus = (k or 0) > 0 and k or nil
  BBT_HubNavParam()
  if not silent then
    funcLuaCommand(1917805374, 2456713098 --[[sy0001]])
  end
  BBT_GroupsShow(BattleBayDeluxe.Tournament.HUB.PAGE)
end

-- the side menu's cursor moved by d (wraps), the dashboard drawn again; silent = no move sound
function BBT_HubMove(d, silent)
  local n = #BattleBayDeluxe.Tournament.HUB.NAV
  BattleBayDeluxe.TournamentState.hub_nav = ((BattleBayDeluxe.TournamentState.hub_nav or 0) + d) % n
  BBT_HubNavParam()
  if not silent then
    funcLuaCommand(1917805374, 2456713098 --[[sy0001]])
  end
  BBT_GroupsShow(BattleBayDeluxe.Tournament.HUB.PAGE)
end

-- ---- mouse / free cursor (evt_menu_kit.lua#Pointer, docs/game/ui/mouse-support.md §5)
-- EVT_PointerNew(): a pointer helper for menus that draw their own selectable items (docs/game/ui/mouse-support.md §5).
-- Mouse and VR's free cursor (the stick-driven «virtual mouse», CMND_SET_ENABLE_FREE_CURSOR_FOR_VIRTUAL_MOUSE) are
-- the same pointer: the engine's pointer position (558229292, screen px, y down) is read every frame and any change
-- (or the engine's «mouse moved», 3272825600) puts the menu in pointer mode; a menu arrow (CMD_UP/DOWN/LEFT/RIGHT)
-- ends it. The menu declares its zones each time it draws, from the same positions it draws with:
--   P.Begin()                              forget the zones of the last drawing
--   P.Rect(x, y, w, h, id[, edge])         top-left + size, screen px (y down)
--   P.Box(cx, cy, hw, hh, id[, edge])      centre + half sizes, screen px (y down)
--   P.Inst(layer, idx, hw, hh, id[, edge]) around a layer instance's global position (read at hit-test time)
--   (edge = -1 / 1: a scroll band; hovering it scrolls every P.REPEAT frames: ev.edge)
-- The last zone declared wins (popups / buttons drawn over cards). Per frame (Step): local ev = P.Poll() with
--   ev.moved   the pointer moved (pointer mode on)          ev.hot / ev.changed  zone id under the pointer / it changed
--   ev.click   id clicked (mouse left button, or Accept / the free cursor's A in pointer mode) on a zone
--   ev.miss    a mouse click on no zone (do nothing; Enter / A there = the menu's key Accept, pointer mode off)
--   ev.wheel   -1 up / 1 down (CMD_EVT_WHEEL_*)
--   ev.edge    -1 / 1 from a scroll band                     ev.keys   a menu arrow was pressed (pointer mode off)
--   ev.hover   the zone under the pointer, only on a frame the pointer MOVED (or was clicked): hover by movement only,
--              so a redraw / scroll / camera move under a resting pointer never re-selects (retail behaviour)
-- P.KeyStep(): the menu moved its selection itself (its own key callbacks, a polled stick / D-pad the arrows above do
-- not see): pointer mode off and the resting position taken as the baseline, so the pad owns the selection until the
-- pointer really moves again or clicks (a resting mouse would otherwise pin the selection under it).
-- Hover = move the selection to ev.hot with the keyboard highlight; ev.click = select it and decide. The menu's own
-- Accept callbacks (OnEnter / OnDecideFocus / a polled CMD_ENTER) return early while P.Owns(): in pointer mode the
-- click belongs to the pointer, so an item not under it is never activated. Zones are only declared for pickable,
-- shown items (never hidden ones). P.Forget() after a redraw under a still pointer re-focuses the zone beneath it.
EVT_PointerNew = EVT_PointerNew or function()
  local P = {zones = {}, on = false, x = nil, y = nil, hot = nil, prev = {}, edge_t = 0, REPEAT = 10}
  local MOVED, POS, GPOS, CHECK, CTRL = 3272825600, 558229292, 4002164178, 4265778440, 1332654303
  local LEFT, CLICK = 218912913 --[[CMD_EVT_MOUSE_LEFT]], 1651523701 --[[CMD_ENTER_CLICK]]
  local W_UP, W_DOWN = 1942756954 --[[CMD_EVT_WHEEL_UP]], 1623431741 --[[CMD_EVT_WHEEL_DOWN]]
  local NAV = {1197218715, 3259546669, 2765147006, 2075023265} -- CMD_UP / DOWN / LEFT / RIGHT
  local CTRLS = {CTRL, 2748927068 --[[analog-move control: the stick's menu moves]]}
  local function M(cmd, ...)
    local ok, a, b = pcall(funcLuaMenuCommand, cmd, ...)
    if ok then return a, b end
    return nil
  end
  local function In(cmd, ctrl)
    local ok, r = pcall(funcLuaCommand, CHECK, ctrl or CTRL, cmd)
    return ok and r == true
  end
  local function Edge(cmd, ctrl)
    local key = ctrl and (tostring(ctrl) .. ":" .. tostring(cmd)) or cmd
    local now = In(cmd, ctrl)
    local was = P.prev[key]
    P.prev[key] = now
    return now and not was
  end
  function P.Begin()
    P.zones = {}
  end
  function P.Rect(x, y, w, h, id, edge)
    P.zones[#P.zones + 1] = {x, y, x + w, y + h, id = id, edge = edge}
  end
  function P.Box(cx, cy, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {cx - hw, cy - hh, cx + hw, cy + hh, id = id, edge = edge}
  end
  function P.Inst(layer, idx, hw, hh, id, edge)
    P.zones[#P.zones + 1] = {layer = layer, idx = idx, hw = hw, hh = hh, id = id, edge = edge}
  end
  function P.Pos()
    local x, y = M(POS)
    if type(x) == "number" and type(y) == "number" then return x, y end
    return nil
  end
  function P.At(x, y)
    if x == nil then x, y = P.x, P.y end
    if x == nil then return nil end
    for i = #P.zones, 1, -1 do
      local z = P.zones[i]
      if z.layer ~= nil then
        local gx, gy = M(GPOS, z.layer, z.idx)
        if type(gx) == "number" and type(gy) == "number" and math.abs(x - gx) <= z.hw and math.abs(-y - gy) <= z.hh then
          return z
        end
      elseif x >= z[1] and x < z[3] and y >= z[2] and y < z[4] then
        return z
      end
    end
    return nil
  end
  -- the Accept being pressed now is a pointer click: the mouse button, or Accept / A in pointer mode ON an item
  -- (Enter / A with the pointer resting on empty space is a key Accept on the current selection)
  function P.Owns()
    return In(LEFT) or (P.on and In(CLICK) and P.At() ~= nil)
  end
  -- forget the hovered zone: the next Poll reports the zone under a still pointer as changed (after a redraw)
  function P.Forget()
    P.hot = nil
  end
  function P.KeyStep()
    P.on, P.hot = false, nil
    local x, y = P.Pos()
    if x ~= nil then P.x, P.y = x, y end
  end
  function P.Reset()
    P.zones, P.on, P.hot, P.prev, P.edge_t = {}, false, nil, {}, 0
    P.x, P.y = P.Pos()
    -- a press / wheel / arrow held from the screen before is no click, no scroll, no key
    for _, c in ipairs({LEFT, CLICK, W_UP, W_DOWN}) do Edge(c) end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do Edge(c, ctrl) end
    end
  end
  function P.Poll()
    local ev = {}
    local x, y = P.Pos()
    if x ~= nil then
      local moved = M(MOVED) == true
      if not moved and P.x ~= nil and (math.abs(x - P.x) > 1 or math.abs(y - P.y) > 1) then
        moved = true    -- the free cursor (stick) moves the pointer without the mouse's «moved» flag
      end
      P.x, P.y = x, y
      if moved then
        P.on, ev.moved = true, true
      end
    end
    for _, ctrl in ipairs(CTRLS) do
      for _, c in ipairs(NAV) do
        if Edge(c, ctrl) then
          ev.keys = true
        end
      end
    end
    if ev.keys and not ev.moved then
      P.on = false
    end
    local left, click = Edge(LEFT), Edge(CLICK)
    if left then
      P.on = true
    end
    local z = P.on and P.At() or nil
    local id = z and z.id or nil
    ev.changed = id ~= P.hot
    P.hot, ev.hot = id, id
    if z ~= nil and (ev.moved or left) then
      ev.hover = id
    end
    if left then
      if z ~= nil then
        ev.click = id
      else
        ev.miss = true                 -- a mouse click on empty space: nothing
      end
    elseif click and P.on then
      if z ~= nil then
        ev.click = id
      else
        P.on, P.hot = false, nil       -- Enter / A on empty space: the menu's key Accept takes it (selection kept)
      end
    end
    if In(W_DOWN) then
      ev.wheel = 1
    elseif In(W_UP) then
      ev.wheel = -1
    end
    if z ~= nil and z.edge ~= nil then
      P.edge_t = P.edge_t - 1
      if P.edge_t <= 0 then
        ev.edge, P.edge_t = z.edge, P.REPEAT
      end
    else
      P.edge_t = 0
    end
    return ev
  end
  return P
end

-- the hub's pointer zones, sent by the drawing menu after each hub drawing (evt_bbd_tn_groups_menu.lua DrawHub, a
-- cross-menu call): "n,<side menu row>,x0,y0,x1,y1;p,<panel>,x0,y0,x1,y1;..." in screen px (y down), from the quads it
-- drew ("c,<matchday>,…": a card of the calendar grid, DrawFixtures); the last one wins where they overlap
function BBT_HubZones(s)
  local zones = {}
  for kind, n, x0, y0, x1, y1 in tostring(s or ""):gmatch("(%a),(%d+),([%d.-]+),([%d.-]+),([%d.-]+),([%d.-]+)") do
    zones[#zones + 1] = { tonumber(x0), tonumber(y0), tonumber(x1), tonumber(y1),
      nav = kind == "n" and tonumber(n) or nil, panel = kind == "p" and tonumber(n) or nil,
      md = kind == "c" and tonumber(n) or nil }
  end
  BattleBayDeluxe.TournamentState.hub_zones = zones
end

-- the zone z focused as the keys would focus it: a side menu row (the dashboard's focus off), a dashboard panel or a
-- card of the calendar grid; silent = a click (its decide sound follows), not a hover
function BBT_HubPointTo(z, silent)
  if z.md ~= nil then
    BBT_HubCalFocus(z.md, silent)
  elseif z.panel ~= nil then
    if BattleBayDeluxe.TournamentState.hub_focus ~= z.panel then
      BBT_HubFocus(z.panel, silent)
    end
  elseif BattleBayDeluxe.TournamentState.hub_focus ~= nil or (BattleBayDeluxe.TournamentState.hub_nav or 0) ~= z.nav then
    BattleBayDeluxe.TournamentState.hub_focus = nil
    BBT_HubMove(z.nav - (BattleBayDeluxe.TournamentState.hub_nav or 0), silent)
  end
end

-- every Step: while the dashboard or the calendar grid waits for its action, hover by movement focuses the element
-- under the pointer and a click decides it (the same action as Enter on it), the wheel turns the grid's pages; idle
-- otherwise (a press held from a page before is no click)
function BBT_HubPointerStep()
  local S = BattleBayDeluxe.TournamentState
  local grid = S.cal_wait == true and S.cal_act == nil
  if not (S.open and ((S.hub_wait and S.hub_act == nil) or grid)) or S.hub_zones == nil then
    S.hub_ptr_idle = true
    return
  end
  local P = S.hub_ptr
  if P == nil then
    P = EVT_PointerNew()
    S.hub_ptr = P
    S.hub_ptr_idle = true
  end
  if S.hub_ptr_idle then
    S.hub_ptr_idle = false
    P.Reset()
  end
  P.Begin()
  for k, z in ipairs(S.hub_zones) do
    P.Rect(z[1], z[2], z[3] - z[1], z[4] - z[2], k)
  end
  local ev = P.Poll()
  if grid and ev.wheel ~= nil then
    BBT_HubCalTurn(ev.wheel)
    return
  end
  local k = ev.click or ev.hover
  local z = k and S.hub_zones[k]
  if z == nil or (grid and z.md == nil) or (not grid and z.md ~= nil) then
    return
  end
  BBT_HubPointTo(z, ev.click ~= nil)
  if ev.click ~= nil then
    if grid then
      S.cal_act = "open"
    else
      S.hub_act = z.panel ~= nil and BattleBayDeluxe.Tournament.HUB.PANELS[z.panel].act or BattleBayDeluxe.Tournament.HUB.NAV[z.nav + 1]
    end
  end
end

-- the hub's own key events (OnDecideFocus / OnBack / OnFunction while it waits): true = taken
function BBT_HubKey(kind, fn)
  if not BattleBayDeluxe.TournamentState.hub_wait then
    return false
  end
  local H = BattleBayDeluxe.Tournament.HUB
  local P = BattleBayDeluxe.TournamentState.hub_ptr
  -- the mouse: its left-click row and an engine Accept that is a pointer click belong to BBT_HubPointerStep
  if fn == H.FN_CLICK or (kind == "enter" and P ~= nil and P.Owns()) then
    return true
  end
  -- a key moves the focus: the pad owns it until the pointer really moves again
  if P ~= nil and kind == "function" then
    P.KeyStep()
  end
  -- 1.58.0: the focus inside the dashboard: the directions follow the panels' layout, Enter = the panel's action,
  -- Back = the side menu again
  local p = BattleBayDeluxe.TournamentState.hub_focus and H.PANELS[BattleBayDeluxe.TournamentState.hub_focus]
  if p then
    if kind == "enter" then
      BattleBayDeluxe.TournamentState.hub_act = p.act
    elseif kind == "back" then
      BBT_HubFocus(0)
    else
      local dir = (fn == H.FN_UP and "up") or (fn == H.FN_DOWN and "down") or (fn == H.FN_LEFT and "left")
        or (fn == H.FN_RIGHT and "right") or nil
      local to = dir and p[dir]
      if to ~= nil then
        BBT_HubFocus(to)
      end
    end
    return true
  end
  if kind == "enter" then
    BattleBayDeluxe.TournamentState.hub_act = H.NAV[(BattleBayDeluxe.TournamentState.hub_nav or 0) + 1]
  elseif kind == "back" then
    BattleBayDeluxe.TournamentState.hub_act = "exit"
  elseif fn == H.FN_RIGHT and (BattleBayDeluxe.TournamentState.hub_nav or 0) == 0 then
    BBT_HubFocus(1)
  elseif fn == H.FN_UP or fn == BattleBayDeluxe.Tournament.FN_PREV then
    BBT_HubMove(-1)
  elseif fn == H.FN_DOWN or fn == BattleBayDeluxe.Tournament.FN_NEXT then
    BBT_HubMove(1)
  end
  return true
end

-- the footer while the dashboard waits: Accept, «Salir» (Back); a click on an entry is its key (1.58.0: «Nueva liga»
-- is a side menu row, no X entry).
-- Off: the overlay's own footer (Accept only)
function BBT_HubGuide(on)
  if BattleBayDeluxe.TournamentHost.name ~= "bb_stadium_top_menu" then
    return
  end
  if not on then
    pcall(BattleBayDeluxe.TournamentHost.guide, true)
    return
  end
  local G = BattleBayDeluxe.Tournament.HUB.GUIDE
  funcLuaMenuCommand(711242136, G, 0, true)
  funcLuaMenuCommand(2209673388 --[[guide entries]], BattleBayDeluxe.TournamentHost.menu, G,
    { 1847312674 --[[Accept]], BBT_Id("hub_exit") },
    { 2750714971 --[[<CMD_ENTER>]], BBT_Id("key_back") }, { 0, 0 }, { 0, 0 }, { 0, 0 })
  funcLuaMenuCommand(452337289 --[[guide commands]], BattleBayDeluxe.TournamentHost.menu, G, { 1981080283 --[[CMD_ENTER]], 3011112225 })
end

-- the dashboard's next action: "play" | "calendar" | "competition" | "roster" | "new" | "exit" (the overlay closed
-- from elsewhere = "exit"); the coroutine sleeps until a key event sets it
function BBT_HubWait()
  BattleBayDeluxe.TournamentState.hub_act = nil
  BattleBayDeluxe.TournamentState.hub_wait = true
  while BattleBayDeluxe.TournamentState.hub_act == nil and BattleBayDeluxe.TournamentState.open do
    coroutine.yield()
  end
  BattleBayDeluxe.TournamentState.hub_wait = nil
  local a = BattleBayDeluxe.TournamentState.hub_act or "exit"
  BattleBayDeluxe.TournamentState.hub_act = nil
  return a
end

-- a section's pages until Enter / Back (BBT_OnEnter / OnBack clear BattleBayDeluxe.TournamentState.section)
function BBT_HubSection(page)
  BBT_Draw(page)
  BattleBayDeluxe.TournamentState.section = true
  while BattleBayDeluxe.TournamentState.section and BattleBayDeluxe.TournamentState.open do
    coroutine.yield()
  end
  BattleBayDeluxe.TournamentState.section = nil
end

-- the calendar page of the last matchday played (the hub's «Últimos resultados»); nil when none was played
function BBT_HubResultsPage(v)
  local played = tonumber(v.played) or 0
  if played < 1 then
    return nil
  end
  return BattleBayDeluxe.Tournament.HUB.CALENDAR_PAGE + (played - 1) * BattleBayDeluxe.Tournament.HUB.CAL_HALVES
end

-- 1.70.0 (owner 2026-10-29: «El calendario tienen que ser todas las jornadas que hay»): the calendar section = the grid of
-- every matchday (view kind "fixtures", drawn by evt_bbd_tn_groups_menu.lua DrawFixtures). The arrows move the focus
-- card by card (Up / Down a row of the view's cols), L1 / R1 turn the grid's pages, Accept (or a click) opens the
-- focused matchday's page (every match of it, the calendar pages: L1 / R1 there turn the matchdays; Enter / Back = the
-- grid again), Back = the hub. Hover by movement focuses a card, the wheel turns the page.

-- the grid drawn again: the focused matchday to the drawing menu, its page drawn (a new page) or redrawn
function BBT_HubCalShow(silent)
  local S = BattleBayDeluxe.TournamentState
  local v = S.view or {}
  local page = BattleBayDeluxe.Tournament.HUB.FIXTURES_FIRST + math.floor((S.cal_md - 1) / math.max(1, S.cal_per))
  VRFW_Param.Clear(BattleBayDeluxe.Tournament.HUB.P_CAL_MD)
  VRFW_Param.Set(BattleBayDeluxe.Tournament.HUB.P_CAL_MD, S.cal_md)
  if not silent then
    funcLuaCommand(1917805374, 2456713098 --[[sy0001]])
  end
  if v.kind == "fixtures" and v.page == page then
    BBT_GroupsShow(page)
  else
    BBT_Draw(page)
  end
end

-- the focus to matchday md (clamped to the league's matchdays)
function BBT_HubCalFocus(md, silent)
  local S = BattleBayDeluxe.TournamentState
  md = math.max(1, math.min(S.cal_mds, md))
  if md ~= S.cal_md then
    S.cal_md = md
    BBT_HubCalShow(silent)
  end
end

-- the grid's keys while it waits (OnDecideFocus / OnBack / OnFunction): true = taken
function BBT_HubCalKey(kind, fn)
  local S = BattleBayDeluxe.TournamentState
  if not S.cal_wait then
    return false
  end
  local H = BattleBayDeluxe.Tournament.HUB
  local P = S.hub_ptr
  if fn == H.FN_CLICK or (kind == "enter" and P ~= nil and P.Owns()) then
    return true
  end
  if P ~= nil and kind == "function" then
    P.KeyStep()
  end
  if kind == "enter" then
    S.cal_act = "open"
  elseif kind == "back" then
    S.cal_act = "back"
  elseif fn == H.FN_LEFT then
    BBT_HubCalFocus(S.cal_md - 1)
  elseif fn == H.FN_RIGHT then
    BBT_HubCalFocus(S.cal_md + 1)
  elseif fn == H.FN_UP or fn == H.FN_DOWN then
    -- a row up / down; none there (the grid's first / last row): the focus stays
    local to = S.cal_md + (fn == H.FN_UP and -S.cal_cols or S.cal_cols)
    if to >= 1 and to <= S.cal_mds then
      BBT_HubCalFocus(to)
    end
  elseif fn == BattleBayDeluxe.Tournament.FN_PREV or fn == BattleBayDeluxe.Tournament.FN_NEXT then
    BBT_HubCalTurn(fn == BattleBayDeluxe.Tournament.FN_NEXT and 1 or -1)
  end
  return true
end

-- a page of the grid turned by d (wraps): the focus on the same place of the new page (its last card when shorter)
function BBT_HubCalTurn(d)
  local S = BattleBayDeluxe.TournamentState
  local pages = math.max(1, math.ceil(S.cal_mds / S.cal_per))
  if pages < 2 then
    return
  end
  local p = math.floor((S.cal_md - 1) / S.cal_per)
  local slot = (S.cal_md - 1) % S.cal_per
  local np = (p + d) % pages
  S.cal_md = math.min(S.cal_mds, np * S.cal_per + slot + 1)
  BBT_HubCalShow()
end

-- the grid until Back (a coroutine step of BBT_LeagueHub); v = the hub's view (fixtures_page / fixtures_md)
function BBT_HubCalendar(v)
  local S = BattleBayDeluxe.TournamentState
  local H = BattleBayDeluxe.Tournament.HUB
  local first = BBT_Call(BattleBayDeluxe.Tournament.VIEW, v.fixtures_page or H.FIXTURES_FIRST)
  if type(first) ~= "table" or first.kind ~= "fixtures" then
    -- no grid (an older view): the matchday's page as before
    BBT_HubSection(v.calendar_page or H.CALENDAR_PAGE)
    return
  end
  S.cal_mds = math.max(1, tonumber(first.mds) or 1)
  S.cal_cols = math.max(1, tonumber(first.cols) or 1)
  S.cal_per = math.max(1, tonumber(first.per) or S.cal_mds)
  S.cal_md = math.max(1, math.min(S.cal_mds, tonumber(v.fixtures_md) or 1))
  BBT_HubCalShow(true)
  while BattleBayDeluxe.TournamentState.open do
    S.cal_act = nil
    S.cal_wait = true
    while S.cal_act == nil and BattleBayDeluxe.TournamentState.open do
      coroutine.yield()
    end
    S.cal_wait = nil
    local a = S.cal_act
    S.cal_act = nil
    if a ~= "open" then
      break
    end
    funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
    BBT_HubSection(H.CALENDAR_PAGE + (S.cal_md - 1) * H.CAL_HALVES)
    if not BattleBayDeluxe.TournamentState.open then
      break
    end
    -- back on the grid: on the matchday the inner pages were turned to
    local pg = tonumber(BattleBayDeluxe.TournamentState.page) or 0
    if pg >= H.CALENDAR_PAGE then
      S.cal_md = math.max(1, math.min(S.cal_mds, math.floor((pg - H.CALENDAR_PAGE) / H.CAL_HALVES) + 1))
    end
    BattleBayDeluxe.TournamentState.view = nil
    BBT_HubCalShow(true)
  end
  if BattleBayDeluxe.TournamentState.open then
    funcLuaCommand(1917805374, 202039849 --[[sy0006]])
  end
  S.cal_wait, S.cal_act = nil, nil
end

-- the hub's loop (a coroutine: BattleBayDeluxe.TournamentState.co, or the entry's decide coroutine)
function BBT_LeagueHub()
  BattleBayDeluxe.TournamentState.hub = true
  local H = BattleBayDeluxe.Tournament.HUB
  BattleBayDeluxe.TournamentState.hub_nav = BattleBayDeluxe.TournamentState.hub_nav or 0
  BattleBayDeluxe.TournamentState.hub_focus = nil
  while true do
    local info = BBT_Info()
    if not info.active or info.fmt ~= 2 then
      break
    end
    BBT_HubNavParam()
    if BattleBayDeluxe.TournamentState.open then
      BBT_Draw(H.PAGE)
    else
      BBT_Open(H.PAGE)
    end
    if not BattleBayDeluxe.TournamentState.open then
      break
    end
    BBT_HubGuide(true)
    local what = BBT_HubWait()
    BBT_HubGuide(false)
    BBT_Log("hub:", what, "side menu row", BattleBayDeluxe.TournamentState.hub_nav)
    local v = BattleBayDeluxe.TournamentState.view or {}
    if what == "dashboard" then
      -- 1.58.0: «Inicio»: the focus into the dashboard (its first panel, the next match)
      BBT_HubFocus(1)
    elseif what == "scorers" then
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      BBT_HubSection(H.SCORERS_PAGE)
      if not BattleBayDeluxe.TournamentState.open then
        break
      end
    elseif what == "results" then
      -- the last matchday played (its results page of the calendar); none yet: the next one
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      BBT_HubSection(BBT_HubResultsPage(v) or v.calendar_page or H.CALENDAR_PAGE)
      if not BattleBayDeluxe.TournamentState.open then
        break
      end
    elseif what == "play" then
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      BattleBayDeluxe.TournamentState.hub = nil
      BBT_PlayNext()
      if not BattleBayDeluxe.TournamentState.open then
        return
      end
      BattleBayDeluxe.TournamentState.hub = true
    elseif what == "calendar" then
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      BBT_HubCalendar(v)
      if not BattleBayDeluxe.TournamentState.open then
        break
      end
    elseif what == "competition" then
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      BBT_HubSection(v.home_page or 10)
      if not BattleBayDeluxe.TournamentState.open then
        break
      end
    elseif what == "roster" then
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      if not BBT_HubTeamEditor() then
        BBT_HubSection(H.SQUAD_PAGE)
      end
      if not BattleBayDeluxe.TournamentState.open then
        break
      end
    elseif what == "new" then
      funcLuaCommand(1917805374, 3848881948 --[[sy0000]])
      local a = BBT_Choose({ BBT_Id("new_yes"), BBT_Id("new_no") }, 1)
      if a == 0 then
        BBT_Call(BattleBayDeluxe.Tournament.ABANDON)
        pcall(funcLuaCommand, BattleBayDeluxe.Tournament.RULE_SELECT, "")
        if BattleBayDeluxe.TournamentState.open then
          BBT_Close()
        end
        BattleBayDeluxe.TournamentState.hub = nil
        BBT_Log("hub: the running league abandoned, a new one")
        return BBT_NewRun(2)
      end
    else
      if BattleBayDeluxe.TournamentState.open then
        funcLuaCommand(1917805374, 202039849 --[[sy0006]])
        BBT_Close()
      end
      break
    end
  end
  BattleBayDeluxe.TournamentState.hub, BattleBayDeluxe.TournamentState.hub_wait, BattleBayDeluxe.TournamentState.hub_act, BattleBayDeluxe.TournamentState.hub_focus = nil, nil, nil, nil
end
-- ===== EVT bb_tournament top league hub END =====

-- ===== EVT bb_tournament top entry BEGIN =====
-- BattleBayDeluxe bb_tournament, top menu part: the entry: continue / view / new from the Campaña row or the hub.
-- Appended after bbt_top.lua in graft.toml's order: the parts share one chunk and its locals.
BattleBayDeluxe = type(BattleBayDeluxe) == "table" and BattleBayDeluxe or {}

-- ------------------------------------------------------------------------------------------------ the entry

-- the «Torneo» row decided (bbt_row.lua; the «Modos de juego» tile or the top bar step): with a run, continue / new
-- (1.5.17, owner: a new tournament even while one runs, after a Yes / No; an ended run: view / new); else (1.5.4,
-- owner's flow) the tournament is armed with the defaults and the Campaña grid opens
-- (1.5.5: through the 1P row's path with the Campaña variant, whether a Campaña runs or not): the team first (the Draft tile
-- too), then the options panel (bbt_grid.lua: group stage, teams, the knockout rules), then the difficulty window; its
-- start draws the tournament (no match starts), and back here the bracket shows the first round: Enter = match 1.
-- Runs in the decide coroutine.
function BBT_EntryTournament()
  BattleBayDeluxe.TournamentState.entry = true
  local ok, err = pcall(BBT_EntryFlow)
  BattleBayDeluxe.TournamentState.entry = false
  if not ok then
    error(err, 0)
  end
end

-- 1.5.18 (owner): the Torneo panel. A run (or an ended one): the bracket opens and the window comes centred over it,
-- «Continuar el torneo» (the next match, or the next simulated round once out) / «Ver el cuadro» (the bracket stays,
-- its keys) / «Nuevo torneo» (Yes / No while one runs; No = the window again); Back = both closed, the player where he
-- was. No run: a new one at once (the team grid).
function BBT_EntryFlow()
  while true do
    local info = BBT_Info()
    if not (info.active or info.ended) then
      return BBT_NewRun()
    end
    -- 1.48.0: a running league opens its career hub
    if info.active and info.fmt == 2 then
      return BBT_LeagueHub()
    end
    BBT_Open(BBT_EntryPage())
    -- 1.45.0: a league's panel says «liga» (the texts <key>_league)
    local lg = info.fmt == 2
    local cont, view, new = BBT_Id(BBT_RunKey("continue", lg)), BBT_Id(BBT_RunKey("view", lg)),
      BBT_Id(BBT_RunKey("new", lg))
    local ids = { cont, view, new }
    if not info.active then
      ids = { view, new }
    end
    -- 1.5.20: the host menu's input is never switched (1.5.19 did: no effect, and it disturbs the engine's input)
    local c = BBT_Choose(ids, 0)
    local id = ids[c + 1]
    if c < 0 or id == nil then
      if BattleBayDeluxe.TournamentState.open then
        funcLuaCommand(1917805374, 202039849 --[[sy0006]])
        BBT_Close()
      end
      return
    end
    if id == cont then
      BBT_OnEnter()
      return
    end
    if id == view then
      return -- the bracket stays up: L1 / R1 pages, Enter = the next match, Back closes
    end
    -- «Nuevo torneo»: a running one is dropped only after a Yes (its Campaña block back, as «Abandonar» did); an
    -- ended one is put aside as its last screen would
    -- 1.5.20 (owner, 1.5.18 / 1.5.19 logs): a retail general window (Yes / No) opened over «Modos de juego» never
    -- takes its answer (the BB Campaña's «Partida nueva» question neither); the question is the same centred
    -- window as the panel instead: «Sí, empezar de cero» / «No, volver», cursor on No
    local go = true
    if info.active then
      local a = BBT_Choose({ BBT_Id("new_yes"), BBT_Id("new_no") }, 1)
      go = a == 0
      BBT_Log("new tournament: answer", go and "yes" or "no", a)
    end
    if go then
      if info.active then
        BBT_Call(BattleBayDeluxe.Tournament.ABANDON)
        BBT_Log("new tournament: the running one abandoned")
      else
        BBT_Call(BattleBayDeluxe.Tournament.CLOSE)
        BBT_Log("new tournament: the ended one put aside")
      end
      pcall(funcLuaCommand, BattleBayDeluxe.Tournament.RULE_SELECT, "")
      if BattleBayDeluxe.TournamentState.open then
        BBT_Close()
      end
      return BBT_NewRun(lg and 2 or -1)
    end
  end
end

-- a new tournament: armed with the defaults, the team grid (the host's way: this menu's 1P path with the Campaña
-- variant, or «Modos de juego»'s own grid), back from it the bracket of the first round (or disarmed)
-- fmt: the format armed (-1 / nil = the tournament's default, 2 = the league: «Nueva liga»)
function BBT_NewRun(fmt)
  local armed, why = BBT_Call(BattleBayDeluxe.Tournament.ARM, fmt or -1, 0, 0)
  if armed ~= true then
    BBT_Log("not armed", tostring(armed), tostring(why))
    return
  end
  -- 1.5.5: the grid opens through the 1P row's own path (no «Campaña in progress» window: the Torneo is independent
  -- of the Campaña), its menu variant swapped to the Campaña's (BBT_OpenGridAsCampaign, 1.5.7: at run time);
  -- 1.5.18: the host's way (BattleBayDeluxe.TournamentHost.open_grid)
  BBT_Log("new tournament: armed, team grid opens on", BattleBayDeluxe.TournamentHost.name)
  BattleBayDeluxe.TournamentState.newrun = true
  local okg, errg = pcall(BattleBayDeluxe.TournamentHost.open_grid)
  BattleBayDeluxe.TournamentState.newrun = false
  if not okg then
    error(errg, 0)
  end
  -- 1.33.2: the grid not opened (the menu never settled): the armed run goes, the top menu stays usable
  if errg == false then
    BBT_Call(BattleBayDeluxe.Tournament.DISARM)
    BBT_Log("new tournament: the team grid did not open, the run is disarmed")
    return
  end
  BBT_Log("new tournament: team grid closed")
  -- back from the grid: a started tournament shows its bracket (the first round); else the armed one goes
  local i3 = BBT_Info()
  if i3.active and i3.fmt == 2 then
    return BBT_LeagueHub()
  elseif i3.active then
    BBT_Open(BBT_EntryPage())
  elseif i3.armed then
    BBT_Call(BattleBayDeluxe.Tournament.DISARM)
  end
end

-- the «Campaña» row of the list: (layer, index, rows), nil when not listed
function BBT_CampaignRow()
  for _, l in ipairs({ BattleBayDeluxe.Tournament.LIST_MID, BattleBayDeluxe.Tournament.LIST_SMALL }) do
    local n = GetNumUsedButtons(l) or 0
    for i = 0, n - 1 do
      local info = GetLitItemInfo(l, i)
      if info ~= nil and info.menuObjectName == BattleBayDeluxe.Tournament.ROW_CAMPAIGN then
        return l, i, n
      end
    end
  end
  return nil
end

-- the menu's focus on the «Campaña» row, handed over as the retail menu hands it between its two lists (OnChangeFocus,
-- WaitExecOtherMenu): only the row's list takes the control focus (with both lists enabled the other one takes the
-- keys at its own stale index), the row focused and lit, the cursor on it, the retail SelectListItem / content guide
-- told (the help text is the row's own)
function BBT_FocusCampaignRow()
  local l, i, n = BBT_CampaignRow()
  if l == nil then
    l, i, n = BattleBayDeluxe.Tournament.LIST_MID, 0, GetNumUsedButtons(BattleBayDeluxe.Tournament.LIST_MID) or 1
  end
  for _, other in ipairs({ BattleBayDeluxe.Tournament.LIST_MID, BattleBayDeluxe.Tournament.LIST_SMALL }) do
    if other ~= l then
      funcLuaMenuCommand(3518307824, other, false)
    end
  end
  funcLuaMenuCommand(3518307824, l, true)
  funcLuaMenuCommand(1778826357 --[[set focus index]], l, i, true)
  funcLuaMenuCommand(3781155141 --[[button anime]], l, i, 1286797620, 0 --[[lit]], 973515837)
  funcLuaMenuCommand(381797568, l, 3313461902 --[[cursor]], i, n)
  pcall(SelectListItem, l)
  pcall(UpdateContentGuide, i)
  return l, i
end

-- the «SIGUIENTE» badge under the «Campaña» row (vs11_01_next_stage_guide): the retail text and crest are the Campaña
-- record's; while a Torneo / Liga runs (the run the «Campaña» row opens) they are its next match: the matchday or the
-- round and the rival with his crest (CMND_BBD_TOURN_INFO next_stage / next_round / rival). No run: the retail badge.
BattleBayDeluxe.Tournament.BADGE = 2575749231 --[[vs11_01_next_stage_guide]]
BattleBayDeluxe.Tournament.BADGE_TEXT = 2060256098
BattleBayDeluxe.Tournament.BADGE_KEYS = { league = "badge_league", groups = "badge_groups", ko = "badge_ko" }
function BBT_NextBadge(info, inst)
  if BattleBayDeluxe.TournamentHost.name ~= "bb_stadium_top_menu" or type(info) ~= "table" or not info.active then
    return false
  end
  local key = BattleBayDeluxe.Tournament.BADGE_KEYS[info.next_stage or ""]
  if key == nil then
    return false
  end
  inst = inst or 0
  local rival = info.rival or 0
  local name = rival ~= 0 and VRFW_Team.Name(rival) or ""
  if name == "" then
    name = BBT_Text("sched_rival_tbd")
  end
  local round = info.next_stage == "ko" and BBT_Text("round_" .. tostring(info.next_round or 1)) or ""
  local s = BBT_TextValue(key, info.next_round or 0)
  s = s:gsub("<ROUND>", function() return round end):gsub("<NAME>", function() return name end)
  funcLuaMenuCommand(1083631230, BattleBayDeluxe.Tournament.BADGE, BattleBayDeluxe.Tournament.BADGE_TEXT, s, inst, 0, true)
  funcLuaMenuCommand(1172899594 --[[fit the text]], BattleBayDeluxe.Tournament.BADGE, inst, BattleBayDeluxe.Tournament.BADGE_TEXT)
  if rival ~= 0 then
    local ok, _, tex = pcall(funcLuaCommand, 2151743654 --[[team info]], rival, 6 --[[crest]], 0)
    if ok and tex ~= nil then
      funcLuaMenuCommand(3190452549, BattleBayDeluxe.Tournament.BADGE, inst, 2487102008, 1212643255, tex, 0, true, true)
    end
  end
  return true
end

-- decide the «Campaña» row in a coroutine (as the hub's own decide runs): mode "tournament" (the top bar's Torneo,
-- the header selector's Torneo after the grid) or "campaign" (the header selector's Campaña over the Torneo)
function BBT_DecideCampaignRow(mode)
  local l, i, n = BBT_CampaignRow()
  if l == nil then
    BBT_Log("no Campaña row in the list:", mode)
    return false
  end
  BattleBayDeluxe.TournamentState.row_mode = mode
  BBT_FocusCampaignRow()
  BattleBayDeluxe.TournamentState.co = coroutine.create(function()
    OnDecideFocus(l, i)
  end)
  BBT_Log("Campaña row decided in mode", mode)
  return true
end

-- the top bar step (Battle Bay › Torneo): the Campaña row in Torneo mode
function BBT_DecideRow()
  BBT_DecideCampaignRow("tournament")
end
